import {
	Component,
	Element,
	Event,
	type EventEmitter,
	Host,
	Method,
	Prop,
	State,
	Watch,
	h,
} from "@stencil/core";
import { remove } from "../../../icons";
import getBootstrapConfig from "../../utils/getBootstrapConfig";
import { hasSlot } from "../../utils/slot";

let id = 0;

/**
 * @since 2.0
 * @status experimental
 *
 * @slot - The tab's content.
 * @slot label - The tab's label
 * @slot prefix - tab's prefix
 * @slot suffix - tab's suffix
 *
 * @part base - The component's base wrapper.
 * @part menu - part that renders the menu slot
 * @part close-button - The close button, which is the icon button's base wrapper.
 */

@Component({
	tag: "hbr-tab",
	styleUrl: "tab.scss",
	shadow: true,
})
export class Tab {
	sheet: CSSStyleSheet = new CSSStyleSheet();
	componentId = `tab-${++id}`;
	tab: HTMLElement;
	@State() hasMenu = false;

	@Element() host: HTMLHbrTabElement;

	/** The name of the tab */
	@Prop({ reflect: true }) name: string;

	/** The name of the tab panel the tab will control. The panel must be located in the same tab group. */
	@Prop({ reflect: true }) panel = "";

	/** Set to true to draw the tab in an active state. */
	@Prop({ reflect: true }) active = false;

	/** When true, the tab will be rendered with a close icon. */
	@Prop({ reflect: true }) closable = false;

	/** If used in tab-popover component */
	/** reflect: false so it doesn't collide with the popover attribute, https://developer.mozilla.org/en-US/docs/Web/HTML/Global_attributes/popover */
	@Prop({ reflect: false }) popOver = false;

	/** Used to notify that tab-popover opened */
	@Prop({ reflect: true }) hover = false;

	/** It's deprecated since v2.0.0. the Global side nav tab */
	@Prop({ reflect: true }) nav = false;

	/** Set to true to draw the tab in a disabled state. */
	@Prop({ reflect: true }) disabled = false;

	/** vertical tab */
	@Prop({ reflect: true, mutable: true }) vertical: boolean;

	/** nested tab */
	@Prop({ reflect: true, mutable: true }) nested: boolean;

	/** collapsed state */
	@Prop({ reflect: true, mutable: true }) collapsed = false;

	/** If the tab -> active by focus, not mouse event */
	@Prop({ reflect: true }) focusEvent = false;

	/** deprecated */
	@Prop({ mutable: true, reflect: true }) arialabelledby: string;

	/** aria-hidden */
	@Prop({ mutable: true, reflect: true }) ariahidden: string | boolean = false;

	/** role */
	@Prop({ reflect: true }) ariarole: string;

	/** The tabs's color sentiment. */
	@Prop({ reflect: true }) sentiment;

	/** Attributes related to screen readers. */
	@Prop() aria: {
		role?: string;
		labelledby?: string;
		describedby?: string;
	};

	/** Emitted to handle uncontrolled component use cases */
	@Event({ eventName: "hbr-click" }) hbrClick: EventEmitter;

	/** Emitted when the tab is closable and the close button is activated. */
	@Event({ eventName: "hbr-close" }) hbrClose: EventEmitter;

	/** Emitted when the tab is activated. */
	@Event({ eventName: "hbr-active" }) hbrActive: EventEmitter;

	connectedCallback() {
		this.handleBaseClick = this.handleBaseClick.bind(this);
		this.handleCloseClick = this.handleCloseClick.bind(this);
		this.handleKeyDown = this.handleKeyDown.bind(this);
		this.handleCloseIconOnKeyDown = this.handleCloseIconOnKeyDown.bind(this);
		this.handleTabActive = this.handleTabActive.bind(this);
		this.handleSlotChange = this.handleSlotChange.bind(this);
	}

	componentWillLoad() {
		const verticalTab = this.host.closest(
			"hbr-tab-vertical",
		) as HTMLHbrTabVerticalElement;
		if (verticalTab) {
			this.collapsed = verticalTab.collapsed;
		}
		this.handleSlotChange();
	}

	componentDidLoad() {
		this.setNestedButtonTriggerTabindex();
	}

	setNestedButtonTriggerTabindex = () => {
		if (this.nested) {
			const button = this.host.querySelector(
				"hbr-button[ariarole='tab']",
			) as HTMLHbrButtonElement;
			if (button) {
				button.setAttribute(
					"tabidx",
					button.disabled ? "-1" : this.active ? "0" : "-1",
				);
			}
		}
	};

	/** Sets focus to the tab. */
	@Method()
	async setFocus(options?: FocusOptions) {
		this.tab?.focus(options);
	}

	/** Removes focus from the tab. */
	@Method()
	async removeFocus() {
		this.tab?.blur();
	}

	@Method()
	async setTabindex() {
		this.tab?.setAttribute("tabindex", this.getTabindex());
	}

	getTabindex = () => {
		return this.disabled
			? "-1"
			: this.nav
			  ? "0"
			  : this.nested
				  ? "-1"
				  : this.active
					  ? "0"
					  : "-1";
	};

	handleBaseClick() {
		!this.disabled && this.hbrClick.emit();
	}

	handleKeyDown(event: KeyboardEvent) {
		if ([" ", "Enter"].includes(event.key)) {
			if (!this.nested) this.tab?.click();
		}
	}

	handleCloseClick() {
		!this.disabled && this.hbrClose.emit();
	}

	handleCloseIconOnKeyDown(e: KeyboardEvent) {
		!this.disabled && e.code === "Enter" && this.hbrClose.emit();
	}

	@Watch("active")
	handleTabActive() {
		this.active && this.hbrActive.emit({ tab: this.host });
		this.setNestedButtonTriggerTabindex();
	}

	@Watch("active")
	setNestedValue() {
		if (this.nested) {
			const slot = this.tab?.querySelector(
				"slot:not([name='prefix']):not([name='suffix'])",
			) as HTMLSlotElement;
			if (!slot) return;
			const element = Array.from(
				slot.assignedElements({ flatten: true }),
			).filter((e) => e.tagName.toLocaleLowerCase() === "hbr-dropdown");
			if (element.length) {
				const dropdown = element[0] as HTMLHbrDropdownElement;
				if (dropdown && !this.active)
					dropdown.value = this.active ? "selected" : "";
			}
		}
	}

	handleSlotChange() {
		this.hasMenu = hasSlot(this.host as unknown as HTMLElement, "menu");
	}

	renderDefaultSlot(variant: string) {
		if (["tab", "nested"].includes(variant) && this.vertical) {
			return (
				<span class="tab__default-slot">
					<slot />
				</span>
			);
		}
		return <slot />;
	}

	render() {
		const customSystemIcons = getBootstrapConfig()?.systemIcons;
		let props = {};
		if (this.popOver) {
			props = {
				"aria-haspopup": this.popOver ? "true" : "false",
				"aria-expanded": this.popOver && this.hover ? "true" : "false",
			};
		}
		const tabIndex = this.getTabindex();

		const parent = this.host.closest("hbr-tab-vertical");
		const variant = parent?.variant ? parent.variant : "";
		if (parent && variant === "nested") {
			parent.getTabs().then((tabs) => {
				if (tabs.includes(this.host)) {
					if (this.active) {
						this.host.setAttribute("aria-current", "true");
					} else {
						this.host.removeAttribute("aria-current");
					}
				}
				this.host.setAttribute("role", "treeitem");
			});
		}

		return (
			// If the user didn't provide an ID, we'll set one so we can link tabs and tab panels with aria labels
			<Host
				id={this.host.id || this.componentId}
				onClick={(e) => {
					if (this.nested) e.stopPropagation();
				}}
				{...(this.aria?.role === "none" //stepper
					? undefined
					: {
							role: this.ariarole || this.nav ? "menuitem" : "tab",
							"aria-selected": this.active ? "true" : "false",
							"aria-disabled": this.disabled ? "true" : "false",
							"aria-haspopup": this.nav && this.popOver ? "true" : false,
							"aria-expanded":
								this.nav && this.popOver ? (this.hover ? "true" : false) : null,
					  })}
			>
				<div
					part="base"
					ref={(el) => {
						this.tab = el;
					}}
					class={{
						tab: true,

						// variants
						"tab--horizontal": !this.vertical && !this.nav,
						"tab--vertical": this.vertical,
						"tab--nav": this.nav,
						"tab--nested": this.nested,
						"tab--popover": this.popOver,
						"tab--closable": this.closable,
						"tab--focusevent": this.focusEvent,

						// states
						"tab--active": this.active || this.hover,
						"tab--disabled": this.disabled,
						"tab--hover": this.hover,
						"tab--collapsed": this.collapsed,
						"tab--variant-tab": variant === "tab",
						"tab--variant-nested": variant === "nested",
					}}
					aria-hidden={this.ariahidden}
					onClick={this.handleBaseClick}
					onKeyDown={this.handleKeyDown}
					tabindex={this.getTabindex()}
					{...props}
				>
					<span part="prefix" class="tab__prefix">
						<slot name="prefix" />
					</span>
					{this.renderDefaultSlot(variant)}
					<span part="label" class="tab__label">
						<slot name="label" />
					</span>
					<span part="suffix" class="tab__suffix">
						<slot name="suffix" />
					</span>
					{this.closable && (
						<hbr-icon-button
							asset={customSystemIcons?.remove || remove}
							arialabel="remove"
							exportparts="base:close-button"
							class="tab__close-button"
							onClick={this.handleCloseClick}
							onKeyDown={this.handleCloseIconOnKeyDown}
							tabindex={tabIndex}
						/>
					)}
					{!this.nav && !this.nested && (
						<span part="indicator" class="tab__indicator" />
					)}
				</div>
				<div
					part="menu"
					class={{
						"tab--menu-horizontal": !this.vertical && !this.nav,
						"tab--menu": true,
						"tab--menu-nested": this.nested,
						"tab--menu-active": this.active,
						"tab--menu-disabled": this.disabled,
					}}
				>
					<slot name="menu" onSlotchange={this.handleSlotChange} />
					{this.nested && (
						<span part="menu-indicator" class="tab--menu__indicator" />
					)}
				</div>
			</Host>
		);
	}
}
